# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

def make_student(last, first):
    return Student("id", last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [
            make_student("Halloway", "Juno"),
            make_student("Zane", "Ola"),
            make_student("Dunmere", "Piet")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Ola"
            ]
        )

    def test_first_name_breaks_ties(self):
        people = [
            make_student("Lee", "Zed"),
            make_student("Lee", "Amy")
        ]
        self.assertEqual(
            seating_rows(people, 5),
            ["Row 1: Lee, Amy | Lee, Zed"]
        )

    def test_bad_seat_counts(self):
        people = [make_student("Lee", "Amy")]
        for count in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(people, count)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
